export const CHEER_LINE="Not a leaf in sight. The lawn is spotless.";export function createCheer(){return{phase:"idle",t:0,armed:!1,done:!1}}export function resetCheer(e){return e.phase="idle",e.t=0,e.armed=!1,e.done=!1,e}export function isCheering(e){return e.phase==="cheer"}export function stepCheer(e,r,t,n){return e.phase==="cheer"?(e.t+=r>0?r:0,e.t>=n.seconds?(e.phase="idle",e.done=!0,"end"):null):t.free?t.spotless?e.armed&&!e.done?(e.phase="cheer",e.t=0,"start"):null:(e.armed=!0,null):null}export function skipCheer(e){return e.phase!=="cheer"?!1:(e.phase="idle",e.done=!0,!0)}export function cheerLift(e,r,t=!1){if(t||e<0||e>=r.hops*r.hopTime)return 0;const n=e%r.hopTime/r.hopTime;return r.hop*4*n*(1-n)}export function cheerFocus(e,r){const t=(r.minX+r.maxX)/2,n=(r.minZ+r.maxZ)/2;return{x:(e.x+t)/2,z:(e.z+n)/2}}
